Codebase Patching Script (applyPatch.py)This utility automates the process of modifying local source files via a standardized, JSON-driven update protocol. It acts as the local deployment bridge between an external orchestration context (such as an AI model) and the physical codebase storage volume.🛠 Operational CoreThe utility reads commands structured inside a local configuration layout or standard input streaming context, performing strict operations based on an instruction array map.Complete Protocol SpecificationThe execution envelope must follow this JSON schema:{
  "patches": [
    {
      "filepath": "string (relative target path from current working directory)",
      "action": "string ('patch' | 'create')",
      "content": "string (fully qualified source file content required only if action is 'create')",
      "diffs": [
        {
          "find": "string (exact block signature matching sequence to remove)",
          "replace": "string (exact block replacement code string to inject)"
        }
      ]
    }
  ]
}
🔄 Action Execution Matrix1. The create ActionIntent: Used to instantiate brand-new workspace modules or to clean-overwrite files completely (e.g., initializing from a touch boundary or a broken lint state).Behavior: Circumvents finding algorithms entirely. It overwrites or generates the target path specified by filepath with the absolute payload found inside the content property.Error Fallback: Fails if directory access permissions are denied or if path syntax errors occur.2. The patch ActionIntent: Used to make surgical adjustments within complex files while preserving surrounding layout code blocks.Behavior: Loops sequentially through the diffs block array. For every object item, it runs an exact text string search matching the find content value and replaces it with the sequence mapped inside the replace property.Error Fallback: If a block cannot find a 1:1 character-accurate string sequence match (due to unexpected indents, white-spaces, or line-breaks), the execution reports an error flag indicator (0/1 blocks updated) but continues safely through the remaining file tracking blocks without hard-crashing.⚠️ Development Constraints for AI Automated EnginesExact Whitespace Requirements: The finding engine looks for exact line breaks (\n or \r\n), tab indent structures, and spacing boundaries. Always extract complete function signatures or include distinct structural context lines inside the find criteria sequence to bypass ambiguity.The Blank-File Target Rule: Never issue a patch action against a newly initialized or completely empty file (such as a shell touch asset). A blank target file contains no text for a find property to locate, causing an immediate update failure. Always upgrade the strategy to a create action instead.Strict JSON String Escaping: Since the entire runtime payload travels inside an integrated JSON structure, all double quotes ("), control sequences, or reverse-slashes (\) present in source target segments must be carefully escaped (\", \\) within the transaction payload to prevent string formatting crashes.

/**
 * play.js - Main Babylon Cinematic Engine with Custom ARKit Diagnostics
 */

BABYLON.TransformNode.prototype.getTotalVertices ??= () => 0;

const speakerEl    = document.getElementById('speaker');
const lineEl       = document.getElementById('line');
const progEl       = document.getElementById('prog-bar');
const platesEl     = document.getElementById('plates');
const loadEl       = document.getElementById('loading');
const startEl      = document.getElementById('start-overlay');
const headToggleEl = document.getElementById('head-toggle');

const sceneData = await fetch('traffic_scene.json').then(r => r.json());

const canvas = document.getElementById('renderCanvas');
const engine = new BABYLON.Engine(canvas, true);
const scene  = new BABYLON.Scene(engine);
window.scene = scene;

scene.ambientColor = new BABYLON.Color3(.04, .04, .08);
scene.clearColor   = new BABYLON.Color4(.03, .03, .07, 1);

const fill = new BABYLON.HemisphericLight('fill', new BABYLON.Vector3(0, 1, 0), scene);
fill.intensity   = .3;
fill.diffuse     = new BABYLON.Color3(.55, .65, 1);
fill.groundColor = new BABYLON.Color3(.04, .04, .08);

const key = new BABYLON.DirectionalLight('key', new BABYLON.Vector3(.2, -1, .4), scene);
key.intensity = .9;
key.diffuse   = new BABYLON.Color3(1, .93, .8);

const spot = new BABYLON.PointLight('spot', new BABYLON.Vector3(0, 2, 1), scene);
spot.diffuse    = new BABYLON.Color3(1, .97, .9);
spot.intensity  = 1.1;
spot.range      = 3.0;

const camera = new BABYLON.FreeCamera('cam', new BABYLON.Vector3(0, 1.6, 1.5), scene);
camera.setTarget(new BABYLON.Vector3(0, 1.55, 0));
camera.minZ = 0.01;

const RHUBARB_MAP = {
  'A': 'ih', 'B': 'ou', 'C': 'oh', 'D': 'aa', 'E': 'ee',
  'F': 'aa', 'G': 'aa', 'H': 'ih', 'X': null
};

const FALLBACK_VOWEL_MAP = {
  'jawOpen': 'aa',
  'mouthFunnel': 'oh',
  'mouthPucker': 'ou',
  'eyeBlinkLeft': 'blink',
  'eyeBlinkRight': 'blink'
};

function evalExprChannel(ch, t) {
  const { times, weights } = ch;
  if (t <= times[0]) return weights[0];
  if (t >= times[times.length - 1]) return weights[weights.length - 1];
  for (let i = 1; i < times.length; i++) {
    if (t <= times[i]) {
      const u = (t - times[i - 1]) / (times[i] - times[i - 1]);
      return weights[i - 1] * (1 - u) + weights[i] * u;
    }
  }
  return weights[weights.length - 1];
}

async function loadFaceJSON(url) {
  if (!url || url.endsWith('.vrma') || url.endsWith('.vrm') || url.endsWith('.glb')) return null;
  let data;
  try { data = await fetch(url).then(r => { if (!r.ok) throw new Error(r.status); return r.json(); }); }
  catch (e) { console.warn('[side] Face JSON fetch failed:', url, e); return null; }

  if (data.mouthCues) {
    const times = [];
    const cues = [];
    for (const cue of data.mouthCues) {
      times.push(cue.start, cue.end);
      cues.push(cue.value, cue.value);
    }
    const duration = data.metadata?.duration ?? times[times.length - 1];
    const channels = ['aa', 'ih', 'uu', 'ee', 'oh'].map(v => ({
      name: v, times,
      weights: times.map((t, i) => RHUBARB_MAP[cues[i]] === v ? 1.0 : 0.0)
    }));
    return { channels, duration, startT: null };
  }

  const { names, frames } = data;
  if (!names?.length || !frames?.length) return null;
  const times    = frames.map(f => f.time);
  const duration = times[times.length - 1] ?? 0;
  const channels = names.map((name, i) => ({
    name, times,
    weights: frames.map(f => f.weights[i] ?? 0),
  }));
  return { channels, duration, startT: null };
}

const actors = {};
window.actors = actors;

async function loadActor(id, vrmPath, worldX) {
  console.log(`%c[DIAG-ACTOR] Starting asset import for ID: "${id}" from: ${vrmPath}`, "color: #4caf50; font-weight: bold;");
  loadEl.textContent = `Loading ${id}…`;
  const preMgrCount = scene.metadata?.vrmManagers?.length ?? 0;
  const preRootIds  = new Set(scene.rootNodes.map(n => n.uniqueId));

  const lastSlash = vrmPath.lastIndexOf('/');
  const rootUrl = lastSlash !== -1 ? vrmPath.substring(0, lastSlash + 1) : '';
  const fileName = lastSlash !== -1 ? vrmPath.substring(lastSlash + 1) : vrmPath;

  await BABYLON.SceneLoader.ImportMeshAsync('', rootUrl, fileName, scene);

  const mgr  = scene.metadata?.vrmManagers?.[preMgrCount];
  const root = scene.rootNodes.find(n => !preRootIds.has(n.uniqueId));
  if (!mgr || !root) { console.error('[side] Load failed for', id); return; }

  root.position.set(worldX, 0, 0);

  const morphMap = new Map();
  const rawMorphNames = [];

  for (const mesh of root.getChildMeshes(false)) {
    const mtm = mesh.morphTargetManager;
    if (!mtm) continue;
    for (let i = 0; i < mtm.numTargets; i++) {
      const mt = mtm.getTarget(i);
      if (!mt.name) continue;

      rawMorphNames.push(mt.name);
      morphMap.set(mt.name, mt);
      morphMap.set(mt.name.toLowerCase(), mt);

      const dot = mt.name.indexOf('.');
      if (dot !== -1) {
        const cleanName = mt.name.slice(dot + 1);
        morphMap.set(cleanName, mt);
        morphMap.set(cleanName.toLowerCase(), mt);
      }
    }
  }

  console.log(`%c[DIAG-ACTOR] "${id}" successfully rigged. Total GPU morph targets extracted: ${rawMorphNames.length}`, "color: #00bcd4;");
  console.log(`[DIAG-ACTOR] Sample of available target keys for "${id}":`, rawMorphNames.slice(0, 15));

  actors[id] = { id, mgr, root, morphMap, faceAnim: null, worldX };
}

const MODEL_PREFIX = 'https://media.githubusercontent.com/media/TLTMedia/valid-vrm-avatars/master/';
const resolveAsset = p => (p && !p.startsWith('http')) ? '../' + p : p;
const resolveVRM = p => {
  if (p.startsWith('http')) return p;
  if (p.startsWith('models/')) return '../' + p;
  if (MODEL_PREFIX.startsWith('http')) return p.replace('models/', MODEL_PREFIX);
  return MODEL_PREFIX + p;
};

const [a0, a1] = sceneData.actors;
await loadActor(a0.id, resolveVRM(a0.vrm), +0.3);
await loadActor(a1.id, resolveVRM(a1.vrm), -0.3);

loadEl.textContent = 'Positioning camera…';
scene.render();

function getFacePos(actor) {
  const bones = actor.mgr?.humanoidBone ?? {};
  const pts = ['leftEye','rightEye','head']
    .map(n => { const b = bones[n]; b?.computeWorldMatrix?.(true); return b?.getAbsolutePosition?.(); })
    .filter(Boolean);
  if (!pts.length) return new BABYLON.Vector3(actor.worldX, 1.6, 0);
  return new BABYLON.Vector3(
    pts.reduce((s,p)=>s+p.x,0)/pts.length,
    pts.reduce((s,p)=>s+p.y,0)/pts.length,
    pts.reduce((s,p)=>s+p.z,0)/pts.length,
  );
}

const faceA = getFacePos(actors[a0.id]);
const faceB = getFacePos(actors[a1.id]);
const mid = faceA.add(faceB).scale(0.5);
const halfW = Math.abs(faceB.x - faceA.x) * 0.5 + 0.15;
const camDist = Math.max(0.65, halfW / Math.tan(37 * Math.PI / 180));

camera.position = new BABYLON.Vector3(mid.x, mid.y, mid.z + camDist);
camera.setTarget(mid);
spot.position   = new BABYLON.Vector3(mid.x, mid.y + 0.4, mid.z + camDist * 0.6);

let headTiltEnabled = true;
const headStates = {};

for (const actor of Object.values(actors)) {
  const head = actor.mgr?.humanoidBone?.head;
  const neck = actor.mgr?.humanoidBone?.neck;
  if (!head) continue;
  headStates[actor.id] = {
    energy: 0, tiltZ: 0, tiltX: 0,
    phase:    Math.random() * Math.PI * 2,
    head,     neck,
    headBase: head.rotationQuaternion?.clone() ?? BABYLON.Quaternion.Identity(),
    neckBase: neck?.rotationQuaternion?.clone() ?? BABYLON.Quaternion.Identity(),
  };
}

function tickHead(actor, now) {
  const s = headStates[actor.id];
  if (!s) return;

  if (!headTiltEnabled) {
    s.tiltZ  *= 0.85;
    s.tiltX  *= 0.85;
    s.energy *= 0.85;
  } else {
    let targetEnergy = 0;
    const fa = actor.faceAnim;
    if (fa?.startT) {
      const t = now - fa.startT;
      const jawCh = fa.channels.find(c => c.name === 'jawOpen' || c.name === 'aa');
      const lipCh = fa.channels.find(c => c.name === 'mouthFunnel' || c.name === 'oh');
      if (jawCh) targetEnergy += evalExprChannel(jawCh, t) * 0.7;
      if (lipCh) targetEnergy += evalExprChannel(lipCh, t) * 0.3;
    }
    s.energy += (targetEnergy - s.energy) * 0.08;
    const driftTarget = Math.sin(now * 0.38 + s.phase) * 0.06;
    s.tiltZ += (driftTarget - s.tiltZ) * 0.04;
    s.tiltX += (s.energy * -0.12 - s.tiltX) * 0.06;
  }

  const headTilt = BABYLON.Quaternion.FromEulerAngles(s.tiltX,       0, s.tiltZ);
  const neckTilt = BABYLON.Quaternion.FromEulerAngles(s.tiltX * 0.4, 0, s.tiltZ * 0.4);
  s.head.rotationQuaternion = s.headBase.multiply(headTilt);
  if (s.neck) s.neck.rotationQuaternion = s.neckBase.multiply(neckTilt);
}

headToggleEl.addEventListener('click', () => {
  headTiltEnabled = !headTiltEnabled;
  headToggleEl.className = headTiltEnabled ? '' : 'off';
});
document.addEventListener('keydown', e => {
  if (e.key.toLowerCase() === 'h') {
    headTiltEnabled = !headTiltEnabled;
    headToggleEl.className = headTiltEnabled ? '' : 'off';
  }
});

const plateMap = {};
for (const def of sceneData.actors) {
  const div = document.createElement('div');
  div.className = 'plate';
  div.textContent = def.id;
  div.id = `plate-${def.id}`;
  platesEl.appendChild(div);
  plateMap[def.id] = div;
}

function setActiveSpeaker(id) {
  for (const [aid, div] of Object.entries(plateMap)) {
    div.className = 'plate' + (aid === id ? ' active' : '');
  }
  const actor = actors[id];
  if (actor) {
    const fp = getFacePos(actor);
    spot.position = new BABYLON.Vector3(fp.x, fp.y + 0.35, fp.z + 0.8);
  }
}

let currentAudio = null;
let currentFaceActor = null;
const _timers = [];
const trackedFailures = new Set();

function setExpression(actor, name, value) {
  const lowerName = name.toLowerCase();
  let routeFound = false;

  // 1. Direct Morph Target Fallback
  if (actor.morphMap.has(name) || actor.morphMap.has(lowerName)) {
    const target = actor.morphMap.get(name) || actor.morphMap.get(lowerName);
    if (target) {
      target.influence = value;
      routeFound = true;
    }
  }

  // 2. VRM 0.0 Legacy BlendShape Manager Routing
  if (!routeFound && actor.mgr && typeof actor.mgr.setBlendShapeWeight === 'function') {
    actor.mgr.setBlendShapeWeight(name, value);
    actor.mgr.setBlendShapeWeight(lowerName, value);
    if (FALLBACK_VOWEL_MAP[name]) {
      actor.mgr.setBlendShapeWeight(FALLBACK_VOWEL_MAP[name], value);
    }
    routeFound = true;
  }

  // 3. VRM 1.0 Expression Engine Routing
  if (!routeFound && actor.mgr?.isVRM1 && actor.mgr.expressionManager) {
    actor.mgr.expressionManager.setExpressionWeight(name, value);
    actor.mgr.expressionManager.setExpressionWeight(lowerName, value);
    routeFound = true;
  }

  // Diagnostics alert for missing parameters
  if (!routeFound && value > 0.1) {
    const failKey = `${actor.id}:${name}`;
    if (!trackedFailures.has(failKey)) {
      trackedFailures.add(failKey);
      console.warn(`%c[DIAG-EXPR] Target key "${name}" cannot be resolved on actor "${actor.id}". It is missing from both geometry morph maps and VRM expression configurations.`, "color: #ff9800; font-weight: bold;");
    }
  }
}

function resetFace(actor) {
  if (!actor?.faceAnim) return;
  for (const ch of actor.faceAnim.channels) {
    setExpression(actor, ch.name, 0);
  }
  actor.faceAnim = null;
}

async function playEvent(event) {
  const actor = actors[event.actor];
  if (!actor) return;

  speakerEl.textContent = event.actor.toUpperCase();
  lineEl.textContent    = event.description ?? '';
  setActiveSpeaker(event.actor);

  if (currentFaceActor && currentFaceActor !== actor) resetFace(currentFaceActor);
  resetFace(actor);

  const faceURL = resolveAsset(event.lipSync || event.layers?.FACE);
  if (faceURL) {
    console.log(`%c[DIAG-TIMELINE] Loading tracking track for "${event.actor}": ${faceURL}`, "color: #e91e63;");
    const fa = await loadFaceJSON(faceURL);
    if (fa) {
      fa.startT = performance.now() / 1000;
      actor.faceAnim = fa;
      currentFaceActor = actor;
      console.log(`[DIAG-TIMELINE] Active tracking channels inside file:`, fa.channels.map(c => c.name));
    }
  }

  if (currentAudio) { currentAudio.pause(); currentAudio = null; }
  if (event.audio) {
    const aud = new Audio(resolveAsset(event.audio));
    aud.play().catch(e => console.warn('[side] audio:', e));
    currentAudio = aud;
  }

  const dur = event.duration ?? 3;
  progEl.style.transition = 'none';
  progEl.style.width = '0%';
  requestAnimationFrame(() => {
    progEl.style.transition = `width ${dur}s linear`;
    progEl.style.width = '100%';
  });
}

function startTimeline() {
  console.log("%c[DIAG-MAIN] Timeline playback triggered by user action.", "color: #9c27b0; font-weight: bold;");
  for (const event of sceneData.timeline) {
    _timers.push(setTimeout(() => playEvent(event), event.start * 1000));
  }
  const last = sceneData.timeline.at(-1);
  if (last) {
    _timers.push(setTimeout(() => {
      speakerEl.textContent = '';
      lineEl.textContent    = '';
      progEl.style.width    = '0%';
      if (currentAudio) { currentAudio.pause(); currentAudio = null; }
      resetFace(currentFaceActor);
      for (const div of Object.values(plateMap)) div.className = 'plate';
    }, (last.start + last.duration + 1) * 1000));
  }
}

loadEl.style.display   = 'none';
startEl.style.display  = 'flex';
startEl.addEventListener('click', () => {
  startEl.style.display = 'none';
  startTimeline();
}, { once: true });

engine.runRenderLoop(() => {
  const now = performance.now() / 1000;
  for (const actor of Object.values(actors)) {
    const fa = actor.faceAnim;
    if (fa?.startT) {
      const t = now - fa.startT;
      if (t > fa.duration + 0.1) {
        for (const ch of fa.channels) setExpression(actor, ch.name, 0);
        actor.faceAnim = null;
      } else {
        for (const ch of fa.channels) setExpression(actor, ch.name, evalExprChannel(ch, t));
      }
    }
    tickHead(actor, now);
  }
  scene.render();
});

window.addEventListener('resize', () => engine.resize());

/**
 * vrm1-loader.js — VRM 1.0 (VRMC_vrm) extension for Babylon.js
 * Optimized for performance and broad Babylon.js version compatibility.
 */
(function () {
  'use strict';

  const EXT_NAME = 'VRMC_vrm';
  const ANIM_EXT_NAME = 'VRMC_vrm_animation';

  class VRM1Extension {
    constructor(loader) {
      this.loader  = loader;
      this.name    = EXT_NAME;
      this.enabled = true;
    }

    dispose() { 
      this.loader = null; 
    }

    onReady() {
      const ext = this.loader.gltf?.extensions?.[EXT_NAME];
      if (!ext) return;

      const humanBones = ext?.humanoid?.humanBones;
      if (!humanBones) return;

      const scene = this.loader.babylonScene;
      const nodeMap = {};
      const humanoidBone = { nodeMap };

      // Map scene objects by name for fast lookup
      const nodeByName = new Map();
      for (const tn of scene.transformNodes) nodeByName.set(tn.name, tn);
      for (const mesh of scene.meshes) {
        if (!nodeByName.has(mesh.name)) nodeByName.set(mesh.name, mesh);
      }

      // Link VRM humanoid bone strings to Babylon nodes safely
      for (const [boneName, boneData] of Object.entries(humanBones)) {
        if (boneData?.node == null) continue;

        // Get the structural glTF node name safely from the index
        const gltfNodeName = this.loader.gltf.nodes?.[boneData.node]?.name;
        if (!gltfNodeName) continue;

        const babylonNode = nodeByName.get(gltfNodeName);

        if (babylonNode) {
          humanoidBone[boneName] = babylonNode;
          nodeMap[boneName] = babylonNode;

          // Tag the node directly so modern Babylon rigging/IK utilities can identify it
          babylonNode.metadata = babylonNode.metadata || {};
          babylonNode.metadata.vrmBoneName = boneName;
        }
      }

      // Maintain scene-level compatibility with the legacy ecosystem
      scene.metadata = scene.metadata || {};
      scene.metadata.vrmManagers = scene.metadata.vrmManagers || [];
      scene.metadata.vrmManagers.push({
        humanoidBone,
        humanBones, 
        meta: ext.meta || {},
        isVRM1: true
      });

      console.log(`[VRM1] Successfully rigged ${Object.keys(nodeMap).length} humanoid bones.`);
    }
  }

  class VRM1AnimationExtension {
    constructor(loader) {
      this.loader  = loader;
      this.name    = ANIM_EXT_NAME;
      this.enabled = true;
    }

    dispose() { 
      this.loader = null; 
    }

    onReady() {
      const ext = this.loader.gltf?.extensions?.[ANIM_EXT_NAME];
      if (!ext) return;

      const scene = this.loader.babylonScene;
      const humanBones = ext.humanoid?.humanBones;
      if (!humanBones) return;

      const animationMap = new Map(); 
      const nameMap      = new Map(); 
      const gltfNodes    = this.loader.gltf.nodes;

      for (const [boneName, boneData] of Object.entries(humanBones)) {
        if (boneData.node != null) {
          animationMap.set(boneData.node, boneName);
          const nodeName = gltfNodes?.[boneData.node]?.name;
          if (nodeName) nameMap.set(nodeName, boneName);
        }
      }

      scene.metadata = scene.metadata || {};
      scene.metadata.vrmAnimationManagers = scene.metadata.vrmAnimationManagers || [];
      scene.metadata.vrmAnimationManagers.push({ animationMap, nameMap });

      console.log('[VRM1] Animation extension ready. Mapped targets:', nameMap.size);
    }
  }

  function register() {
    // Check global scope safely
    const BABYLON_GLOBAL = typeof window !== 'undefined' ? window.BABYLON : (typeof globalThis !== 'undefined' ? globalThis.BABYLON : null);
    const GL = BABYLON_GLOBAL?.GLTF2?.GLTFLoader;

    if (!GL) {
      // Retry safely if Babylon isn't fully initialized on the page yet
      setTimeout(register, 30);
      return;
    }

    GL.RegisterExtension(EXT_NAME, loader => new VRM1Extension(loader));
    GL.RegisterExtension(ANIM_EXT_NAME, loader => new VRM1AnimationExtension(loader));
    console.log('[VRM1] Extensions registered successfully.');
  }

  // Handle various script loading entry configurations safely
  if (typeof document !== 'undefined' && document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', register);
  } else {
    register();
  }
})();

/**
 * Character.js - Handles VRM Rig, Morph Mappings, and Transform Deltas
 */
import { ExtendedVRMManager } from "./VRMFaceExtension.js";

export class Character {
    constructor(id, rootNode, vrmManager) {
        this.id = id;
        this.root = rootNode;
        this.mgr = vrmManager;
        this.curGroups = [];

        this.face = new ExtendedVRMManager(vrmManager, rootNode);
        this.vrmAvatar = new BABYLON.AnimatorAvatar(`avatar-${id}`, rootNode);

        // Procedural head movement state
        this.headState = {
            energy: 0, tiltZ: 0, tiltX: 0,
            phase: Math.random() * Math.PI * 2,
            head: vrmManager.humanoidBone?.head,
            neck: vrmManager.humanoidBone?.neck,
            headBase: vrmManager.humanoidBone?.head?.rotationQuaternion?.clone() ?? BABYLON.Quaternion.Identity(),
            neckBase: vrmManager.humanoidBone?.neck?.rotationQuaternion?.clone() ?? BABYLON.Quaternion.Identity()
        };
    }

    stopAnimations() {
        this.curGroups.forEach(g => { g.stop(); g.dispose(); });
        this.curGroups = [];
    }

    resetFace() {
        if (this.activeExpressions) {
            // Force zeroing out all blendshapes that were active
            const names = this.activeExpressions.map(e => e.name);
            const zeros = names.map(() => 0);
            this.face.applyExpressionFrame(names, zeros);
        }
        this.activeExpressions = [];
    }

    tickProceduralHead(now, activeExpressions) {
        const s = this.headState;
        if (!s.head) return;

        let targetEnergy = 0;
        // Jaw movement drives head energy
        const jaw = activeExpressions.find(e => e.name.toLowerCase() === 'jawopen' || e.name.toLowerCase() === 'aa');
        if (jaw) targetEnergy += jaw.val * 0.6;

        s.energy += (targetEnergy - s.energy) * 0.08;
        s.tiltZ += (Math.sin(now * 0.4 + s.phase) * 0.04 - s.tiltZ) * 0.04;
        s.tiltX += (s.energy * -0.1 - s.tiltX) * 0.06;

        s.head.rotationQuaternion = s.headBase.multiply(BABYLON.Quaternion.FromEulerAngles(s.tiltX, 0, s.tiltZ));
        if (s.neck) {
            s.neck.rotationQuaternion = s.neckBase.multiply(BABYLON.Quaternion.FromEulerAngles(s.tiltX * 0.4, 0, s.tiltZ * 0.4));
        }
    }
}

/**
 * main.js - Core application lifecycle entry point
 */
import { Stage } from "./Stage.js";
import { Character } from "./Character.js";
import { TimelineManager } from "./Timeline.js";

BABYLON.TransformNode.prototype.getTotalVertices ??= () => 0;

const loadEl = document.getElementById("loading");
const lineEl = document.getElementById("line");
const canvasEl = document.getElementById("renderCanvas");
const actors = {};

const stage = new Stage("renderCanvas");
const sceneData = await fetch("traffic_scene.json").then(r => r.json());

const resolveVRM = p => {
    if (p.startsWith("http")) return p;
    // Force lookups to search up one level in the common directory layout
    if (p.startsWith("models/")) return "../" + p;
    return p;
};

async function initializeActor(def) {
    loadEl.textContent = `Hydrating ${def.id}…`;
    const beforeCount = stage.scene.metadata?.vrmManagers?.length ?? 0;
    const animBeforeCount = stage.scene.metadata?.vrmAnimationManagers?.length ?? 0;
    const existingRoots = new Set(stage.scene.rootNodes.map(n => n.uniqueId));

    const fullPath = resolveVRM(def.vrm);
    console.log(`[Main] Loading actor ${def.id} from ${fullPath}`);

    await BABYLON.SceneLoader.ImportMeshAsync(
        null,        
        fullPath,    
        null,        
        stage.scene  
    );

    const mgr = stage.scene.metadata?.vrmManagers?.[beforeCount];
    const root = stage.scene.rootNodes.find(n => !existingRoots.has(n.uniqueId));

    if (!mgr || !root) {
        console.error(`[Main] Asset initialization failed for ${def.id}. Mgr: ${!!mgr}, Root: ${!!root}`);
        throw new Error(`Asset initialization crashed for identifier: ${def.id}`);
    }

    console.log(`[Main] Actor ${def.id} ready. Root name: ${root.name}`);
    root.position.set(def.startPosition?.x ?? 0, def.startPosition?.y ?? 0, def.startPosition?.z ?? 0);
    actors[def.id] = new Character(def.id, root, mgr);
}

try {
    for (const actorDef of (sceneData.actors ?? [])) {
        await initializeActor(actorDef);
    }
} catch (err) {
    console.error("Critical loading failure:", err.message);
}

loadEl.style.display = "none";
lineEl.textContent = "Click to begin";

canvasEl.addEventListener("click", () => {
    lineEl.textContent = "";
    const timeline = new TimelineManager(stage, actors);
    stage.startRenderLoop();
    timeline.run(sceneData.timeline);
}, { once: true });

/**
 * Stage.js - Manages the Scene, Lighting rig, and Camera behaviors
 */
export class Stage {
    constructor(canvasId) {
        this.canvas = document.getElementById(canvasId);
        this.engine = new BABYLON.Engine(this.canvas, true);
        this.scene = new BABYLON.Scene(this.engine);

        this.setupEnvironment();
        this.setupLights();
        this.setupCamera();

        window.addEventListener("resize", () => this.engine.resize());
    }

    setupEnvironment() {
        this.scene.ambientColor = new BABYLON.Color3(0.05, 0.05, 0.1);
        this.scene.clearColor = new BABYLON.Color4(0.04, 0.04, 0.08, 1);
    }

    setupLights() {
        this.keyLight = new BABYLON.DirectionalLight("key", new BABYLON.Vector3(0.3, -1, 0.5), this.scene);
        this.keyLight.intensity = 1.2;
        this.keyLight.diffuse = new BABYLON.Color3(1, 0.95, 0.85);

        this.fillLight = new BABYLON.HemisphericLight("fill", new BABYLON.Vector3(0, 1, 0), this.scene);
        this.fillLight.intensity = 0.35;
        this.fillLight.diffuse = new BABYLON.Color3(0.6, 0.7, 1);
        this.fillLight.groundColor = new BABYLON.Color3(0.05, 0.04, 0.08);
    }

    setupCamera() {
        this.camera = new BABYLON.ArcRotateCamera(
            "cam", 
            Math.PI / 2, 
            Math.PI / 2 - 0.22, 
            4.2, 
            new BABYLON.Vector3(0, 1.05, 0),
            this.scene
        );
        this.camera.attachControl(this.canvas, true);
        this.camera.lowerRadiusLimit = 1;
        this.camera.upperRadiusLimit = 12;
    }

    startRenderLoop() {
        this.engine.runRenderLoop(() => this.scene.render());
    }
}

/**
 * Timeline.js - Synchronous Audio Event Processor, VRMA Retargeter, and Array-Based Expression Streamer
 */
export class TimelineManager {
    constructor(stage, actors) {
        this.stage = stage;
        this.actors = actors;

        this.progEl = document.getElementById("prog-bar");
        this.speakerEl = document.getElementById("speaker");
        this.lineEl = document.getElementById("line");
        this.dumpEl = document.getElementById("tracking-dump");

        this.offsets = {
            jordan: { position: new BABYLON.Vector3(0, 0, 0) },
            officer: { position: new BABYLON.Vector3(1.2, 0, 0.3) }
        };

        this._setupGlobalTick();
    }

    _setupGlobalTick() {
        this.stage.scene.onBeforeRenderObservable.add(() => {
            const now = performance.now() / 1000;
            let hudHtml = "";

            for (const actor of Object.values(this.actors)) {
                // Tick procedural head movement
                actor.tickProceduralHead(now, actor.activeExpressions || []);

                // Collect HUD data
                if (actor.activeExpressions && actor.activeExpressions.length > 0) {
                    actor.activeExpressions.forEach(e => {
                        hudHtml += `<div class="track-row"><span>${actor.id}.${e.name}</span><span class="track-val">${e.val.toFixed(2)}</span></div>`;
                    });
                }
            }

            if (this.dumpEl) {
                this.dumpEl.innerHTML = hudHtml || "<div style='opacity:0.4'>No active blendshapes</div>";
            }
        });
    }

    resolveAsset(p) {
        return (p && !p.startsWith("http")) ? "../" + p : p;
    }

    async loadAndRetargetVRMA(actor, url, name) { 
        console.log(`[Timeline Engine] Loading VRMA: ${name} from ${url}`);
        const scene = this.stage.scene;

        const managersBefore = new Set(scene.metadata?.vrmAnimationManagers ?? []);

        let container;
        try { 
            container = await BABYLON.LoadAssetContainerAsync(url, scene); 
        } catch (e) { 
            console.error("[Timeline Engine] Failed to load VRMA layer:", url, e); 
            return null; 
        }

        // Find the newly added manager
        const managersAfter = scene.metadata?.vrmAnimationManagers ?? [];
        const vrmAnimMgr = managersAfter.find(m => !managersBefore.has(m));
        const srcGroup = container.animationGroups[0];

        if (!vrmAnimMgr || !srcGroup) {
            console.warn(`[Timeline Engine] VRMA assets missing in ${url}. Mgr: ${!!vrmAnimMgr}, Group: ${!!srcGroup}`);
            container.dispose();
            return null;
        }

        console.log(`[Timeline Engine] Retargeting ${srcGroup.name} to ${actor.id}...`);

        const mapNodeNames = new Map();
        srcGroup.targetedAnimations.forEach((ta, i) => {
            const boneName = vrmAnimMgr.animationMap.get(i);
            const bone = actor.mgr.humanoidBone[boneName];
            if (bone && ta.target?.name) {
                mapNodeNames.set(ta.target.name, bone.name);
            }
        });

        if (mapNodeNames.size === 0) {
            console.warn(`[Timeline Engine] No bone mappings found for ${url}`);
            container.dispose();
            return null;
        }

        const remapped = actor.vrmAvatar.retargetAnimationGroup(srcGroup, {
            animationGroupName: `${actor.id}-${name}`,
            fixRootPosition: true,
            rootNodeName: actor.mgr.humanoidBone["hips"]?.name,
            groundReferenceNodeName: actor.mgr.humanoidBone["leftFoot"]?.name,
            mapNodeNames,
        });

        console.log(`[Timeline Engine] Successfully remapped ${name} for ${actor.id}. Tracks: ${remapped.targetedAnimations.length}`);

        container.dispose();
        return remapped;
    }

    async playEvent(event) {
        const actor = this.actors[event.actor];
        if (!actor) return;

        this.speakerEl.textContent = event.actor.toUpperCase();
        this.lineEl.textContent = event.description ?? "";

        const hips = actor.mgr.humanoidBone["hips"];
        if (hips && actor.curGroups.length > 0) {
            const worldHips = hips.getAbsolutePosition();
            this.offsets[event.actor].position.x = worldHips.x;
            this.offsets[event.actor].position.z = worldHips.z;
        }

        actor.stopAnimations();
        Object.values(this.actors).forEach(a => a.resetFace());
        actor.root.position.copyFrom(this.offsets[event.actor].position);

        const targetX = actor.root.position.x * 0.4;
        this.stage.camera.setTarget(
            BABYLON.Vector3.Lerp(this.stage.camera.target, new BABYLON.Vector3(targetX, 1.05, 0), 0.6)
        );

        const layers = event.layers || {};
        const groups = [];
        for (const [name, url] of Object.entries(layers)) {
            if (name === "FACE") continue; 
            const g = await this.loadAndRetargetVRMA(actor, this.resolveAsset(url), name);
            if (g) groups.push(g);
        }
        actor.curGroups = groups;
        groups.forEach(g => g.start(false, 1.0, g.from, g.to, false));

        if (event.audio) {
            const audio = new Audio(this.resolveAsset(event.audio));
            let trackingData = null;

            if (event.lipSync) {
                try { 
                    trackingData = await fetch(this.resolveAsset(event.lipSync)).then(r => r.json()); 
                } catch(e) { 
                    console.warn("[Timeline Engine] Error fetching high-fidelity facial JSON:", e); 
                }
            }

            let renderObs = this.stage.scene.onBeforeRenderObservable.add(() => {
                const clock = audio.currentTime;
                const ratio = audio.duration > 0 ? clock / audio.duration : 0;
                this.progEl.style.width = (ratio * 100).toFixed(1) + "%";

                if (trackingData && trackingData.frames && trackingData.names) {
                    actor.activeExpressions = actor.face.evaluateInterpolated(trackingData.names, trackingData.frames, clock);
                } 
            });

            await new Promise(res => {
                audio.onended = () => { 
                    this.stage.scene.onBeforeRenderObservable.remove(renderObs); 
                    actor.resetFace();
                    res(); 
                };
                audio.onerror = () => { 
                    this.stage.scene.onBeforeRenderObservable.remove(renderObs); 
                    actor.resetFace();
                    res(); 
                };
                audio.play().catch(res);
            });
        }
        this.progEl.style.width = "0%";
    }

    async run(timeline) {
        for (let i = 0; i < timeline.length; i++) {
            await this.playEvent(timeline[i]);
            await new Promise(r => setTimeout(r, 400));
        }
        this.speakerEl.textContent = "";
        this.lineEl.textContent = "— end —";
    }
}

/**
 * VRMFaceExtension.js - High-performance ARKit morph target streamer
 */
export class ExtendedVRMManager {
    constructor(vrmManager, rootNode) {
        this.baseMgr = vrmManager;
        this.root = rootNode;
        this.cachedTargets = new Map();
        this.arkitMap = {
            'jawopen': 'aa', 'mouthfunnel': 'oh', 'mouthpucker': 'ou',
            'eyeblinkleft': 'blinkleft', 'eyeblinkright': 'blinkright',
            'mouthsmileleft': 'happy', 'mouthsmileright': 'happy'
        };

        this._cacheARKitTargets();
    }

    _cacheARKitTargets() {
        for (const mesh of this.root.getChildMeshes(false)) {
            const mtm = mesh.morphTargetManager;
            if (!mtm) continue;

            for (let i = 0; i < mtm.numTargets; i++) {
                const target = mtm.getTarget(i);
                if (!target.name) continue;

                const cleanName = target.name.includes(".") 
                    ? target.name.split(".").pop().toLowerCase() 
                    : target.name.toLowerCase();

                this.cachedTargets.set(cleanName, target);
                // Also cache normalized alphanumeric name
                this.cachedTargets.set(cleanName.replace(/[^a-z0-9]/g, ''), target);
            }
        }
    }

    applyExpressionFrame(names, weights) {
        const active = [];
        for (let i = 0; i < weights.length; i++) {
            const val = weights[i];
            const name = names[i].toLowerCase();
            const target = this.cachedTargets.get(name) || 
                         this.cachedTargets.get(name.replace(/[^a-z0-9]/g, '')) ||
                         (this.arkitMap[name] ? this.cachedTargets.get(this.arkitMap[name]) : null);

            if (target) {
                target.influence = val;
                if (val > 0.1) active.push({ name: names[i], val });
            }
        }
        return active;
    }

    // Helper for linear interpolation between frames
    evaluateInterpolated(names, frames, time) {
        if (!frames || frames.length === 0) return [];

        let weights;
        if (time <= frames[0].time) {
            weights = frames[0].weights;
        } else if (time >= frames[frames.length - 1].time) {
            weights = frames[frames.length - 1].weights;
        } else {
            for (let i = 1; i < frames.length; i++) {
                if (time <= frames[i].time) {
                    const prev = frames[i - 1];
                    const next = frames[i];
                    const u = (time - prev.time) / (next.time - prev.time);
                    weights = prev.weights.map((w, idx) => w * (1 - u) + (next.weights[idx] ?? w) * u);
                    break;
                }
            }
        }

        return this.applyExpressionFrame(names, weights || []);
    }
}
